layer.css:
@import url("https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600;700&display=swap");
[data-ryt="pitch"] { color: #8a90b0; border-left: 2px solid rgb(139, 233, 253); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14.72px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(168, 176, 216); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.2px; padding-right: 0px; padding-bottom: 7.2px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: rgba(40, 42, 54, 0.14); border-top: 1px solid rgba(139, 146, 184, 0.28); border-right: 1px solid rgba(139, 146, 184, 0.28); border-bottom: 1px solid rgba(139, 146, 184, 0.28); border-left: 1px solid rgba(139, 146, 184, 0.28); border-radius: 0px; transition: all }
[data-ryt="footer"] { color: #8a90b0; border-top: 1px solid rgba(139, 146, 184, 0.28); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #5a939f; border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 233, 253); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"] { color: rgb(139, 233, 253); background-color: rgba(139, 233, 253, 0.08); border-top: 1px solid rgba(139, 233, 253, 0.85); border-right: 1px solid rgba(139, 233, 253, 0.85); border-bottom: 1px solid rgba(139, 233, 253, 0.85); border-left: 1px solid rgba(139, 233, 253, 0.85); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 233, 253); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(139, 233, 253, 0.25) 0px 0px 12px; padding-top: 4px; padding-right: 11.2px; padding-bottom: 4px; padding-left: 11.2px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: #9b79cb; background-color: rgba(189, 147, 249, 0.043); border-top: 1px solid rgba(189, 147, 249, 0.55); border-right: 1px solid rgba(189, 147, 249, 0.55); border-bottom: 1px solid rgba(189, 147, 249, 0.55); border-left: 1px solid rgba(189, 147, 249, 0.55); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(189, 147, 249); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 11.2px; padding-bottom: 4px; padding-left: 11.2px; transition: all }
[data-ryt="review"] { color: #8a90b0; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(168, 176, 216); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #379d51; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(80, 250, 123); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #848482; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 248, 242); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: radial-gradient(circle at 50% 0%, rgba(80, 85, 140, 0.28) 0%, rgba(0, 0, 0, 0) 38%), linear-gradient(rgb(27, 30, 58) 0%, rgb(24, 26, 42) 42%, rgb(16, 17, 26) 100%); background-size: auto, auto; background-position: 0% 0%, 0% 0%; background-repeat: repeat, repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: #848482; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 248, 242); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { border-top-color: rgba(139, 233, 253, 0.85); border-right-color: rgba(139, 233, 253, 0.85); border-bottom-color: rgba(139, 233, 253, 0.85); border-left-color: rgba(139, 233, 253, 0.85); background-image: initial; background-color: rgba(139, 233, 253, 0.08); text-shadow: rgba(139, 233, 253, 0.25) 0px 0px 12px }
[data-ryt="button"]:hover { border-top-color: rgba(139, 233, 253, 0.85); border-right-color: rgba(139, 233, 253, 0.85); border-bottom-color: rgba(139, 233, 253, 0.85); border-left-color: rgba(139, 233, 253, 0.85); color: #8be9fd; background-image: initial; background-color: rgba(139, 233, 253, 0.08); text-shadow: rgba(139, 233, 253, 0.25) 0px 0px 12px }
article[data-ryt="rec-card"]:hover { border-top-color: rgba(255, 121, 198, 0.48); border-right-color: rgba(255, 121, 198, 0.48); border-bottom-color: rgba(255, 121, 198, 0.48); border-left-color: rgba(255, 121, 198, 0.48); background-image: initial; background-color: rgba(40, 42, 54, 0.24) }
